UPDATE public.courses c SET status='approved' FROM expected e
WHERE c.id=e.id AND c.name=e.name AND c.description=e.description AND c.lat=e.lat AND c.lng=e.lng AND c.path IS NULL AND c.tags=e.tags AND c.diff=e.diff AND c.distance=e.distance AND c.author=e.author AND c.status='pending'
RETURNING c.id,c.name,c.status;
